'use client';
import { DndContext, DragOverEvent } from '@dnd-kit/core';
import { useState } from 'react';

type Cols = Record<string, string[]>;
export function {{board_name}}() {
  const [cols, setCols] = useState<Cols>({ todo: ['t1'], doing: ['t2'], done: [] });
  function onDragOver(e: DragOverEvent) {
    const { active, over } = e; if (!over) return;
    const from = Object.keys(cols).find(k => cols[k].includes(String(active.id)));
    const to = String(over.id);
    if (!from || from === to) return;
    setCols(c => ({ ...c, [from]: c[from].filter(x => x !== active.id), [to]: [...c[to], String(active.id)] }));
  }
  return <DndContext onDragOver={onDragOver}>{/* render columns + draggable cards */}</DndContext>;
}
